const fs = require('fs');
const path = require('path');
const raw = $input.first().json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
if (!body.file_path) { throw new Error('No file_path in payload. Got keys: ' + Object.keys(raw).join(',')); }
if (!body.title)     { throw new Error('No title in payload'); }
// Normalize separators and translate watcher path -> n8n mount.
let filePath = body.file_path.replace(/\\/g, '/');
if (filePath.startsWith('/downloads/')) {
  filePath = '/shared/downloads/' + filePath.slice('/downloads/'.length);
}
// If we got pointed at a subtitle/info/thumb file, find the merged .mp4 in the same dir.
const lower = filePath.toLowerCase();
if (!lower.endsWith('.mp4')) {
  const dir = path.dirname(filePath);
  try {
    const files = fs.readdirSync(dir);
    const mp4s = files.filter(f => f.toLowerCase().endsWith('.mp4') && !/\.f\d+\.mp4$/i.test(f));
    if (mp4s.length === 0) throw new Error('No .mp4 found in ' + dir + ' (saw: ' + files.join(', ') + ')');
    filePath = path.join(dir, mp4s[0]).replace(/\\/g, '/');
  } catch (e) {
    throw new Error('Cannot list dir ' + dir + ': ' + e.message);
  }
}
// Sanity check
if (!fs.existsSync(filePath)) throw new Error('Resolved file does not exist: ' + filePath);
const stat = fs.statSync(filePath);
console.log('[project003] Resolved video: ' + filePath + ' (' + Math.round(stat.size/1024/1024) + ' MB)');
return [{
  json: {
    job_id:         body.job_id         || null,
    destination_id: body.destination_id || null,
    pipeline_id:    body.pipeline_id    || null,
    video_id:       body.video_id       || null,
    title:        body.title        || 'Untitled Video',
    file_path:    filePath,
    file_size_mb: Math.round(stat.size/1024/1024),
    source_url:   body.source_url   || '',
    channel_name: body.channel_name || '',
    channel_id:   body.channel_id   || '',
    channel_url:  body.channel_url  || '',
    duration:     body.duration     || 0,
    timestamp:    body.timestamp    || new Date().toISOString(),
    description:  `Downloaded from ${body.channel_name || 'YouTube'}.\nSource: ${body.source_url || ''}`,
  }
}];

const original = $('Prepare Video Data').first().json;
let aiData = null;
try {
  const aiResponse = $('AI: Enrich Metadata').first().json;
  const content = aiResponse?.choices?.[0]?.message?.content;
  if (content) {
    const cleaned = content.replace(/```json/gi, '').replace(/```/g, '').trim();
    aiData = JSON.parse(cleaned);
  }
} catch (e) { console.log('[project003] AI parse failed: ' + e.message); }
const result = {
  job_id:         original.job_id,
  destination_id: original.destination_id,
  pipeline_id:    original.pipeline_id,
  video_id:       original.video_id,
  youtube_title:       (aiData?.youtube_title       || original.title).substring(0, 100),
  youtube_description:  aiData?.youtube_description || original.description,
  youtube_tags:         aiData?.youtube_tags        || [],
  title:        original.title,
  file_path:    original.file_path,
  source_url:   original.source_url,
  channel_name: original.channel_name,
  ai_used:      !!aiData,
};
console.log('[project003] AI: ' + (aiData ? 'SUCCESS' : 'FALLBACK') + ' — ' + result.youtube_title);
return [{ json: result }];

const meta = $('AI: Parse & Fallback').first().json;
let ytResult = { status: 'skipped' };
try {
  const ytData = $('YouTube Upload').first().json;
  if (ytData && ytData.id) {
    ytResult = { status: 'success', video_id: ytData.id, url: 'https://youtube.com/watch?v=' + ytData.id };
  } else if (ytData && ytData.error) {
    ytResult = { status: 'error', error: ytData.error.message || JSON.stringify(ytData.error) };
  } else {
    ytResult = { status: 'error', error: 'Unexpected response: ' + JSON.stringify(ytData) };
  }
} catch (e) {
  ytResult = { status: 'error', error: e.message };
}
const summary = {
  job_id:         meta.job_id,
  destination_id: meta.destination_id,
  title:          meta.title,
  ai_title:       meta.youtube_title,
  ai_description: meta.youtube_description,
  ai_tags:        meta.youtube_tags,
  ai_used:        !!meta.ai_used,
  youtube:        ytResult,
};
const icon = ytResult.status === 'success' ? '[OK]' : '[FAIL]';
console.log('[project003] ' + icon + ' ' + meta.title + ' -> YouTube: ' + ytResult.status);
if (ytResult.url) console.log('[project003] Published: ' + ytResult.url);
return [{ json: summary }];
